draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var h = 6.63e-34;
var m = Math.pow(10, p.logm);
var v = Math.pow(10, p.logv);
var lam = h / (m * v);
var logL = Math.log(lam) / Math.LN10;

var pad = 40;
var axY = H * 0.62;
var lo = -36, hi = 0;
var X = function (q) { return pad + (q - lo) / (hi - lo) * (W - 2 * pad); };

ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(pad, axY); ctx.lineTo(W - pad, axY); ctx.stroke();

var dec;
ctx.fillStyle = C.faint;
for (dec = lo; dec <= hi; dec += 2) {
  ctx.beginPath(); ctx.moveTo(X(dec), axY - 4); ctx.lineTo(X(dec), axY + 4); ctx.stroke();
}
ctx.fillStyle = C.figure;
ctx.textAlign = "center";
ctx.fillText("10^-36 m", X(-36) + 8, axY + 18);
ctx.fillText("10^-18 m", X(-18), axY + 18);
ctx.fillText("1 m", X(0) - 6, axY + 18);

var marks = [
  [-15, "nucleus"],
  [-10, "atom"],
  [-7, "virus"],
  [-4, "hair"]
];
var i;
for (i = 0; i < marks.length; i++) {
  var mx = X(marks[i][0]);
  ctx.strokeStyle = C.faint;
  ctx.setLineDash([3, 4]);
  ctx.beginPath(); ctx.moveTo(mx, axY - 34); ctx.lineTo(mx, axY); ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = C.figure;
  ctx.fillText(marks[i][1], mx, axY - 40);
}

var clamped = Math.max(lo, Math.min(hi, logL));
var px = X(clamped);
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(px, axY + 6); ctx.lineTo(px, axY + 34); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.moveTo(px, axY + 4); ctx.lineTo(px - 5, axY + 14); ctx.lineTo(px + 5, axY + 14);
ctx.closePath(); ctx.fill();
ctx.fillText("wavelength", Math.max(pad + 30, Math.min(W - pad - 30, px)), axY + 48);

ctx.textAlign = "left";
ctx.fillStyle = C.ink;
ctx.fillText("mass " + m.toExponential(1) + " kg, speed " + v.toExponential(1) + " m/s", pad, 20);
ctx.fillStyle = C.figure;
var verdict = logL > -9 ? "long enough to diffract from anything" : (logL > -13 ? "atomic scale: crystals will diffract it" : "far too small to ever diffract");
ctx.fillText(verdict, pad, 38);
ctx.textAlign = "left";

out.note = "lambda = h / mv = " + lam.toExponential(2) + " m";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var lam = 1.226 / Math.sqrt(p.volts);
var s = lam / (2 * p.spacing);
var ok = s <= 1;
var th = ok ? Math.asin(s) : Math.PI / 4;

var pad = 24;
var surfY = H * 0.60;
var cx = W * 0.52;

var r, x;
ctx.fillStyle = C.faint;
for (r = 0; r < 3; r++) {
  for (x = pad; x < W - pad; x += 24) {
    ctx.beginPath(); ctx.arc(x, surfY + 6 + r * 22, 3.5, 0, Math.PI * 2); ctx.fill();
  }
}
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
for (r = 0; r < 3; r++) {
  ctx.beginPath(); ctx.moveTo(pad, surfY + 6 + r * 22); ctx.lineTo(W - pad, surfY + 6 + r * 22); ctx.stroke();
}
ctx.strokeStyle = C.figure;
ctx.beginPath(); ctx.moveTo(W - pad - 30, surfY + 6); ctx.lineTo(W - pad - 30, surfY + 28); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.textAlign = "right";
ctx.fillText("d", W - pad - 36, surfY + 21);
ctx.textAlign = "left";

var ct = Math.cos(th), st = Math.sin(th);
var rayLen = Math.min((cx - pad) / Math.max(ct, 0.05), (surfY - pad - 14) / Math.max(st, 0.05));
var pxPerNm = 200;
var kpx = 2 * Math.PI / Math.max(lam * pxPerNm, 4);
var amp = 7;
var u, a, sx, sy;

ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.6;
ctx.beginPath();
for (u = 0; u <= rayLen; u += 1.5) {
  a = Math.sin(kpx * u - 5 * t) * amp;
  sx = cx - (rayLen - u) * ct - a * st;
  sy = surfY - (rayLen - u) * st + a * ct;
  if (u === 0) ctx.moveTo(sx, sy); else ctx.lineTo(sx, sy);
}
ctx.stroke();

if (ok) {
  var outLen = Math.min((W - pad - cx) / Math.max(ct, 0.05), (surfY - pad - 14) / Math.max(st, 0.05));
  ctx.strokeStyle = C.figure;
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  for (u = 0; u <= outLen; u += 1.5) {
    a = Math.sin(kpx * u - 5 * t) * amp;
    sx = cx + u * ct + a * st;
    sy = surfY - u * st + a * ct;
    if (u === 0) ctx.moveTo(sx, sy); else ctx.lineTo(sx, sy);
  }
  ctx.stroke();
  ctx.strokeStyle = C.rule;
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.arc(cx, surfY, 30, -th, 0); ctx.stroke();
  ctx.fillStyle = C.ink;
  ctx.fillText("theta", cx + 34, surfY - 6);
} else {
  ctx.fillStyle = C.ink;
  ctx.textAlign = "center";
  ctx.fillText("wavelength longer than 2d: no first-order peak", W / 2, surfY - 60);
  ctx.textAlign = "left";
}

ctx.fillStyle = C.ink;
ctx.fillText("electron beam", pad, 18);
ctx.fillStyle = C.figure;
ctx.fillText("crystal planes", pad, surfY + 78);

out.note = ok
  ? "lambda = " + lam.toFixed(4) + " nm, first-order Bragg angle = " + (th * 180 / Math.PI).toFixed(1) + " deg"
  : "lambda = " + lam.toFixed(4) + " nm is longer than 2d = " + (2 * p.spacing).toFixed(3) + " nm";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var n = Math.round(p.n);
var L = p.L;
var lam = 2 * L / n;
var E = n * n * 1240 * 1240 / (8 * 511000 * L * L);

var padx = 46;
var x0 = padx, x1 = W - padx;
var mid = H * 0.52;
var amp = H * 0.24;

ctx.strokeStyle = C.ink;
ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(x0, mid - amp - 18); ctx.lineTo(x0, mid + amp + 18); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x1, mid - amp - 18); ctx.lineTo(x1, mid + amp + 18); ctx.stroke();

ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(x0, mid); ctx.lineTo(x1, mid); ctx.stroke();

var env = Math.cos(2.2 * t);
var i, xx, yy;
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath();
for (i = 0; i <= 120; i++) {
  xx = x0 + (x1 - x0) * i / 120;
  yy = mid - amp * Math.sin(n * Math.PI * i / 120);
  if (i === 0) ctx.moveTo(xx, yy); else ctx.lineTo(xx, yy);
}
ctx.stroke();
ctx.beginPath();
for (i = 0; i <= 120; i++) {
  xx = x0 + (x1 - x0) * i / 120;
  yy = mid + amp * Math.sin(n * Math.PI * i / 120);
  if (i === 0) ctx.moveTo(xx, yy); else ctx.lineTo(xx, yy);
}
ctx.stroke();
ctx.setLineDash([]);

ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (i = 0; i <= 160; i++) {
  xx = x0 + (x1 - x0) * i / 160;
  yy = mid - amp * env * Math.sin(n * Math.PI * i / 160);
  if (i === 0) ctx.moveTo(xx, yy); else ctx.lineTo(xx, yy);
}
ctx.stroke();

ctx.fillStyle = C.figure;
for (i = 1; i < n; i++) {
  xx = x0 + (x1 - x0) * i / n;
  ctx.beginPath(); ctx.arc(xx, mid, 3, 0, Math.PI * 2); ctx.fill();
}

ctx.strokeStyle = C.figure;
ctx.lineWidth = 1;
var ay = mid + amp + 30;
ctx.beginPath(); ctx.moveTo(x0, ay); ctx.lineTo(x1, ay); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x0, ay - 4); ctx.lineTo(x0, ay + 4); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x1, ay - 4); ctx.lineTo(x1, ay + 4); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.textAlign = "center";
ctx.fillText("L = " + L.toFixed(2) + " nm holds " + n + " half-wavelengths", (x0 + x1) / 2, ay + 16);
ctx.textAlign = "left";
ctx.fillStyle = C.ink;
ctx.fillText("n = " + n, x0 + 6, mid - amp - 24);

out.note = "lambda = 2L/n = " + lam.toFixed(3) + " nm, electron energy = " + E.toFixed(1) + " eV";
